candidates.raw:
adcs_vec3_t axis;
adcs_status_t st;
double omega_unclamped;
double omega_next;
double norm;
if ((wheel == NULL) || (next_wheel == NULL) || (next_momentum == NULL) || (saturated == NULL)) {
    return ADCS_E_NULL;
}
if ((!adcs_is_finite_vec3(&wheel->axis_body)) || (!isfinite(wheel->inertia_kg_m2)) ||
    (!isfinite(wheel->speed_rad_s)) || (!isfinite(motor_torque)) || (!isfinite(dt)) ||
    (!isfinite(speed_limit)) || (wheel->inertia_kg_m2 <= 0.0) || (dt < 0.0) ||
    (speed_limit <= 0.0)) {
    return ADCS_E_RANGE;
}
st = adcs_vec3_normalize(&wheel->axis_body, ADCS_EPS_NORM, &axis);
if (st == ADCS_E_NULL) {
    return ADCS_E_NULL;
}
if (st != ADCS_OK) {
    return ADCS_E_RANGE;
}
norm = adcs_vec3_norm(&axis);
if (norm <= 1.0e-12) {
    return ADCS_E_RANGE;
}
omega_unclamped = wheel->speed_rad_s + motor_torque * dt / wheel->inertia_kg_m2;
*saturated = (fabs(omega_unclamped) > speed_limit) ? 1 : 0;
omega_next = ADCS_CLAMP(omega_unclamped, -speed_limit, speed_limit);
next_wheel->axis_body = axis;
next_wheel->inertia_kg_m2 = wheel->inertia_kg_m2;
next_wheel->speed_rad_s = omega_next;
*next_momentum = adcs_vec3_scale(&axis, wheel->inertia_kg_m2 * omega_next);
return ADCS_OK;
}

